# Build a RAG App with LlamaIndex: evidence gate for a RAG answer.
question = "Can I get a refund after 35 days without an invoice?"
chunks = [
    {"id": "refunds-v3", "text": "Refund requests require an invoice id and must arrive within 30 days."},
    {"id": "tone-guide", "text": "Use short, friendly support replies."},
]
required_terms = {"invoice", "30 days"}

def supports_answer(chunk):
    text = chunk["text"].lower()
    return all(term in text for term in required_terms)

best = next((c for c in chunks if supports_answer(c)), None)
print(best["id"] if best else "no evidence")
print("answer with citation" if best else "ask for more evidence")

